  1→/**
  2→ * @fileoverview Streaming parser for harness stdout/stderr text.
  3→ *
  4→ * Emits structured events for questions, progress, file ops, errors, and completion.
  5→ *
  6→ * @module harness/output-parser
  7→ */
  8→
  9→import { EventEmitter } from 'events';
 10→import stripAnsi from 'strip-ansi';
 11→
 12→// ============================================================================
 13→// Types
 14→// ============================================================================
 15→
 16→/**
 17→ * Event types emitted by `OutputParser`.
 18→ */
 19→export type ParserEventType =
 20→  | 'line'        // Complete line received
 21→  | 'question'    // Question detected
 22→  | 'progress'    // Progress update
 23→  | 'file_op'     // File operation detected
 24→  | 'error'       // Error pattern detected
 25→  | 'complete';   // Completion detected
 26→
 27→/**
 28→ * File operation categories parsed from output text.
 29→ */
 30→export type FileOperation = 'create' | 'modify' | 'delete';
 31→
 32→/**
 33→ * Parsed file operation event payload.
 34→ */
 35→export interface FileOperationEvent {
 36→  operation: FileOperation;
 37→  path: string;
 38→}
 39→
 40→/**
 41→ * Parsed progress event payload.
 42→ */
 43→export interface ProgressEvent {
 44→  message: string;
 45→  percent?: number;
 46→}
 47→
 48→/**
 49→ * Parser runtime configuration.
 50→ */
 51→export interface ParserConfig {
 52→  /** Strip ANSI escape codes */
 53→  stripAnsi: boolean;
 54→  /** Maximum line length before forcing a break */
 55→  maxLineLength: number;
 56→}
 57→
 58→/**
 59→ * Default parser settings.
 60→ */
 61→const DEFAULT_CONFIG: ParserConfig = {
 62→  stripAnsi: true,
 63→  maxLineLength: 10000,
 64→};
 65→
 66→// ============================================================================
 67→// Common Patterns
 68→// ============================================================================
 69→
 70→/**
 71→ * Patterns used to identify user-input prompts.
 72→ */
 73→const QUESTION_PATTERNS = [
 74→  /^\s*\?\s+(.+)/,              // ? prefix
 75→  /^(.+\?)\s*$/,                // Ends with ?
 76→  /\[y\/n\]/i,                  // [Y/n]
 77→  /\(yes\/no\)/i,               // (yes/no)
 78→  /press enter to continue/i,   // Press enter
 79→  /continue\?\s*$/i,            // Continue?
 80→  /proceed\?\s*$/i,             // Proceed?
 81→  /confirm\?\s*$/i,             // Confirm?
 82→];
 83→
 84→/**
 85→ * Patterns used to identify progress output.
 86→ */
 87→const PROGRESS_PATTERNS = [
 88→  /^[⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏]\s*(.+)$/,     // Spinner
 89→  /^\[[\s=>#-]+\]\s*(\d+)%/,    // Progress bar [=====>   ] 50%
 90→  /^(\d+)%\s+complete/i,        // 50% complete
 91→  /^Working on\s+(.+)/i,        // Working on...
 92→  /^Processing\s+(.+)/i,        // Processing...
 93→  /^Analyzing\s+(.+)/i,         // Analyzing...
 94→];
 95→
 96→/**
 97→ * Patterns used to identify file operation lines.
 98→ */
 99→const FILE_OP_PATTERNS: Array<{ pattern: RegExp; operation: FileOperation }> = [
100→  { pattern: /^Created?\s+(.+)$/i, operation: 'create' },
101→  { pattern: /^Wrote\s+(.+)$/i, operation: 'create' },
102→  { pattern: /^Edited?\s+(.+)$/i, operation: 'modify' },
103→  { pattern: /^Modified?\s+(.+)$/i, operation: 'modify' },
104→  { pattern: /^Updated?\s+(.+)$/i, operation: 'modify' },
105→  { pattern: /^Deleted?\s+(.+)$/i, operation: 'delete' },
106→  { pattern: /^Removed?\s+(.+)$/i, operation: 'delete' },
107→];
108→
109→/**
110→ * Patterns used to identify error lines.
111→ */
112→const ERROR_PATTERNS = [
113→  /^error:/i,
114→  /^Error:/,
115→  /^ERROR:/,
116→  /^fatal:/i,
117→  /^FATAL:/,
118→  /failed to/i,
119→  /permission denied/i,
120→  /not found/i,
121→  /does not exist/i,
122→];
123→
124→/**
125→ * Patterns used to identify completion lines.
126→ */
127→const COMPLETION_PATTERNS = [
128→  /^Done\.?$/i,
129→  /^Completed\.?$/i,
130→  /^Finished\.?$/i,
131→  /^Task completed/i,
132→  /^All done/i,
133→  /^Successfully/i,
134→];
135→
136→// ============================================================================
137→// OutputParser Class
138→// ============================================================================
139→
140→/**
141→ * Parses line-oriented harness output and emits structured events.
142→ */
143→export class OutputParser extends EventEmitter {
144→  /** Parser configuration */
145→  private config: ParserConfig;
146→
147→  /** Line buffer */
148→  private buffer: string = '';
149→
150→  /** All complete lines received */
151→  private lines: string[] = [];
152→
153→  /** Detected file operations */
154→  private fileOps: FileOperationEvent[] = [];
155→
156→  /** Whether completion was detected */
157→  private completed: boolean = false;
158→
159→  /**
160→   * Creates a parser with optional config overrides.
161→   *
162→   * @param config - Parser configuration
163→   */
164→  constructor(config: Partial<ParserConfig> = {}) {
165→    super();
166→    this.config = { ...DEFAULT_CONFIG, ...config };
167→  }
168→
169→  // ==========================================================================
170→  // Public API
171→  // ==========================================================================
172→
173→  /**
174→   * Appends stream data and processes complete lines.
175→   *
176→   * @param data - Data to parse (string or Buffer)
177→   */
178→  write(data: string | Buffer): void {
179→    let text = typeof data === 'string' ? data : data.toString('utf-8');
180→
181→    // Strip ANSI codes if configured
182→    if (this.config.stripAnsi) {
183→      text = stripAnsi(text);
184→    }
185→
186→    // Add to buffer
187→    this.buffer += text;
188→
189→    // Process complete lines
190→    this.processBuffer();
191→  }
192→
193→  /**
194→   * Processes any buffered trailing content.
195→   */
196→  flush(): void {
197→    if (this.buffer.trim()) {
198→      this.processLine(this.buffer.trim());
199→    }
200→    this.buffer = '';
201→  }
202→
203→  /**
204→   * Clears all parser state.
205→   */
206→  reset(): void {
207→    this.buffer = '';
208→    this.lines = [];
209→    this.fileOps = [];
210→    this.completed = false;
211→  }
212→
213→  /**
214→   * Returns all parsed lines.
215→   *
216→   * @returns Array of complete lines
217→   */
218→  getLines(): string[] {
219→    return [...this.lines];
220→  }
221→
222→  /**
223→   * Returns collected output as one string.
224→   *
225→   * @returns All output joined with newlines
226→   */
227→  getOutput(): string {
228→    return this.lines.join('\n');
229→  }
230→
231→  /**
232→   * Returns parsed file operation events.
233→   *
234→   * @returns Array of file operations
235→   */
236→  getFileOperations(): FileOperationEvent[] {
237→    return [...this.fileOps];
238→  }
239→
240→  /**
241→   * Returns true when completion text has been seen.
242→   *
243→   * @returns True if completion pattern was found
244→   */
245→  isCompleted(): boolean {
246→    return this.completed;
247→  }
248→
249→  /**
250→   * Returns the most recent detected question, if any.
251→   *
252→   * @returns Question text if found, null otherwise
253→   */
254→  findQuestion(): string | null {
255→    // Check last few lines for question patterns
256→    const recentLines = this.lines.slice(-5);
257→
258→    for (const line of recentLines.reverse()) {
259→      for (const pattern of QUESTION_PATTERNS) {
260→        const match = line.match(pattern);
261→        if (match) {
262→          return match[1]?.trim() || line.trim();
263→        }
264→      }
265→    }
266→
267→    return null;
268→  }
269→
270→  // ==========================================================================
271→  // Private Methods
272→  // ==========================================================================
273→
274→  /**
275→   * Splits buffered text into complete lines and processes each.
276→   */
277→  private processBuffer(): void {
278→    // Split on newlines
279→    const parts = this.buffer.split(/\r?\n/);
280→
281→    // Process all complete lines (all but the last part)
282→    for (let i = 0; i < parts.length - 1; i++) {
283→      const line = parts[i];
284→      if (line || line === '') {
285→        this.processLine(line);
286→      }
287→    }
288→
289→    // Keep the incomplete last part in buffer
290→    this.buffer = parts[parts.length - 1];
291→
292→    // Force line break if buffer too long
293→    if (this.buffer.length > this.config.maxLineLength) {
294→      this.processLine(this.buffer);
295→      this.buffer = '';
296→    }
297→  }
298→
299→  /**
300→   * Stores and classifies one complete output line.
301→   */
302→  private processLine(line: string): void {
303→    // Store line
304→    this.lines.push(line);
305→
306→    // Emit line event
307→    this.emit('line', line);
308→
309→    // Check for patterns
310→    this.checkQuestion(line);
311→    this.checkProgress(line);
312→    this.checkFileOp(line);
313→    this.checkError(line);
314→    this.checkCompletion(line);
315→  }
316→
317→  /**
318→   * Emits `question` when line matches a question pattern.
319→   */
320→  private checkQuestion(line: string): void {
321→    for (const pattern of QUESTION_PATTERNS) {
322→      const match = line.match(pattern);
323→      if (match) {
324→        const question = match[1]?.trim() || line.trim();
325→        this.emit('question', { question });
326→        return;
327→      }
328→    }
329→  }
330→
331→  /**
332→   * Emits `progress` when line matches a progress pattern.
333→   */
334→  private checkProgress(line: string): void {
335→    for (const pattern of PROGRESS_PATTERNS) {
336→      const match = line.match(pattern);
337→      if (match) {
338→        const event: ProgressEvent = {
339→          message: match[1]?.trim() || line.trim(),
340→        };
341→
342→        // Try to extract percentage
343→        const percentMatch = line.match(/(\d+)%/);
344→        if (percentMatch) {
345→          event.percent = parseInt(percentMatch[1], 10);
346→        }
347→
348→        this.emit('progress', event);
349→        return;
350→      }
351→    }
352→  }
353→
354→  /**
355→   * Emits `file_op` when line matches a file operation pattern.
356→   */
357→  private checkFileOp(line: string): void {
358→    for (const { pattern, operation } of FILE_OP_PATTERNS) {
359→      const match = line.match(pattern);
360→      if (match) {
361→        const event: FileOperationEvent = {
362→          operation,
363→          path: match[1].trim(),
364→        };
365→
366→        this.fileOps.push(event);
367→        this.emit('file_op', event);
368→        return;
369→      }
370→    }
371→  }
372→
373→  /**
374→   * Emits `error` when line matches an error pattern.
375→   */
376→  private checkError(line: string): void {
377→    for (const pattern of ERROR_PATTERNS) {
378→      if (pattern.test(line)) {
379→        this.emit('error', { message: line.trim() });
380→        return;
381→      }
382→    }
383→  }
384→
385→  /**
386→   * Marks parser completed and emits `complete` when matched.
387→   */
388→  private checkCompletion(line: string): void {
389→    for (const pattern of COMPLETION_PATTERNS) {
390→      if (pattern.test(line)) {
391→        this.completed = true;
392→        this.emit('complete', { message: line.trim() });
393→        return;
394→      }
395→    }
396→  }
397→}
398→
399→// ============================================================================
400→// Utility Functions
401→// ============================================================================
402→
403→/**
404→ * Extracts a summary string from parser output lines.
405→ *
406→ * @param parser - Parser with collected output
407→ * @returns Summary string
408→ */
409→export function extractSummary(parser: OutputParser): string {
410→  const lines = parser.getLines();
411→
412→  // Look for explicit summary
413→  const summaryIndex = lines.findIndex((l) => /^##?\s*summary/i.test(l));
414→  if (summaryIndex >= 0) {
415→    const summaryLines: string[] = [];
416→    for (let i = summaryIndex + 1; i < lines.length; i++) {
417→      if (lines[i].startsWith('#')) break;
418→      if (lines[i].trim()) summaryLines.push(lines[i]);
419→    }
