      const gate = await SecurityGate.create();
      expect(gate.hasFetchTrigger('@FETCH hello')).toBe(true);
      expect(gate.hasFetchTrigger('@Fetch hello')).toBe(true);
    });

    it('returns false for messages without trigger', async () => {
      const gate = await SecurityGate.create();
      expect(gate.hasFetchTrigger('hello world')).toBe(false);
    });

